-- Seed bank soal TOEFL ITP — dihasilkan otomatis dari bank versi HTML.
begin;

on conflict (id) do update set title=excluded.title, body=excluded.body, script=excluded.script;

on conflict (id) do update set stem=excluded.stem, opts=excluded.opts, ans=excluded.ans, exp=excluded.exp, skill=excluded.skill, script=excluded.script;

commit;